/* Result-only layout: original frozen PNG and JS bindings stay unchanged.
   ID scope wins over the later shared sheet without changing manual/fallback dialogs. */
#result.throw-result{
  position:fixed;
  inset:calc(16px + env(safe-area-inset-top)) calc(16px + env(safe-area-inset-right)) calc(16px + env(safe-area-inset-bottom)) calc(16px + env(safe-area-inset-left));
  margin:auto;
  width:min(1080px,calc(100vw - 32px - env(safe-area-inset-left) - env(safe-area-inset-right)));
  max-width:none;
  height:fit-content;
  max-height:calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
  padding:24px;
  overflow:auto;
  overscroll-behavior:contain;
  touch-action:pan-y;
  font-size:1rem;
  line-height:1.5;
}
#result.throw-result .throw-result__top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 16px;}
#result.throw-result .throw-result__top>*{margin:0;font-size:.6875rem;line-height:1.4;font-weight:800;letter-spacing:.06em;}
#result.throw-result .throw-result__layout{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,1fr);grid-template-areas:"photo report";align-items:center;gap:24px;}
#result.throw-result .throw-result__report{grid-area:report;display:grid;gap:10px;min-width:0;}
#result.throw-result h2{margin:0;font-size:1.625rem;line-height:1.3;letter-spacing:-.02em;overflow-wrap:anywhere;}
#result.throw-result .resultScore,#result.throw-result .big-score{display:block;margin:0;font-size:clamp(2.25rem,4.5vw,3.5rem);line-height:1.1;font-weight:900;letter-spacing:-.04em;overflow-wrap:anywhere;}
#result.throw-result #verdict{margin:0;font-size:1.125rem;line-height:1.5;font-weight:800;overflow-wrap:anywhere;}
#result.throw-result .throw-result__play{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:0;}
#result.throw-result .throw-result__play button{min-width:0;min-height:48px;margin:0;padding:10px 8px;font-size:.9375rem;line-height:1.3;overflow-wrap:anywhere;}
#result.throw-result .pf-share-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:0;}
#result.throw-result [role="status"]{margin:0;min-height:1.5em;font-size:.75rem;line-height:1.5;overflow-wrap:anywhere;}
#result.throw-result .throw-result__note{display:block;margin:0;font-size:.6875rem;line-height:1.5;color:#64786e;overflow-wrap:anywhere;}
#result.throw-result .throw-result__photo{grid-area:photo;min-width:0;margin:0;padding:12px;border:1px solid #d3dcc9;border-radius:16px;background:#e9eddf;}
#result.throw-result .throw-result__photo img{display:block;width:100%;height:auto;max-height:min(440px,calc(100dvh - 180px));margin:0 auto;object-fit:contain;border-radius:8px;}
#result.throw-result .throw-result__photo img:not([src]){display:none;}
#result.throw-result .throw-result__photo figcaption{margin-top:8px;font-size:.6875rem;line-height:1.5;text-align:center;color:#64786e;}
#result.throw-result summary:focus-visible,#result.throw-result [tabindex="-1"]:focus{outline:2px solid currentColor;outline-offset:3px;}
@media(max-width:799px){
  #result.throw-result{padding:16px;}
  #result.throw-result .throw-result__top{margin-bottom:12px;}
  #result.throw-result .throw-result__layout{grid-template-columns:minmax(0,1fr);grid-template-areas:"report" "photo";gap:16px;}
  #result.throw-result .throw-result__report{gap:8px;}
  #result.throw-result h2{font-size:1.5rem;}
  #result.throw-result .resultScore,#result.throw-result .big-score{font-size:clamp(2.25rem,8vw,3rem);}
  #result.throw-result .throw-result__photo img{max-height:min(280px,45dvh);}
}

/* Only play surfaces: result/fallback images and selectable share text stay native. */
#stage,#stage *,.controls,.controls *{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;}

